drop policy if exists "candidates authorised insert" on public.candidates;
create policy "candidates authorised insert" on public.candidates for insert to authenticated with check (public.candidate_processing_allowed(company_id) and company_id=private.current_company_id() and (private.has_candidate_data_access() or (private.partner_is_active() and exists(select 1 from public.partner_profiles pp where pp.user_id=(select auth.uid()) and pp.company_id=candidates.company_id and pp.active and pp.specialism=any(array['candidate_sourcer'::text,'hybrid'::text])))));
drop policy if exists "candidates authorised select" on public.candidates;
create policy "candidates authorised select" on public.candidates for select to authenticated using (public.candidate_processing_allowed(company_id) and company_id=private.current_company_id() and (private.has_candidate_data_access() or (private.partner_is_active() and exists(select 1 from public.partner_assignments a where a.company_id=candidates.company_id and a.partner_id=(select auth.uid()) and a.candidate_id=candidates.id and a.completed_at is null))));
drop policy if exists "candidates authorised update" on public.candidates;
create policy "candidates authorised update" on public.candidates for update to authenticated using (public.candidate_processing_allowed(company_id) and company_id=private.current_company_id() and (private.has_candidate_data_access() or (private.partner_is_active() and exists(select 1 from public.partner_assignments a where a.company_id=candidates.company_id and a.partner_id=(select auth.uid()) and a.candidate_id=candidates.id and a.completed_at is null)))) with check (public.candidate_processing_allowed(company_id) and company_id=private.current_company_id() and (private.has_candidate_data_access() or private.partner_is_active()));
